#!/usr/bin/env bash
# Stage V03 helper: make ONE controlled, reversible adaptation of the pinned
# RFSoC-MTS ZCU208 project for the Vivado 2023.2 lock.
#
# Why: upstream mts.tcl was generated by Vivado 2022.1.2 and references
# xilinx.com:ip:zynq_ultra_ps_e:3.4 (check-IP list + create_bd_cell).  The
# 2023.2 catalog carries zynq_ultra_ps_e:3.5 instead (introduced in 2023.1),
# so sourcing the pristine file in 2023.2 stops at its CHECK IPs section.
# This script copies the fetched upstream tree to build/mts_base_src_2023p2/
# and applies ONLY that VLNV substitution -- driven by the pinned value, not
# a hard-coded guess in this script -- then prints the exact diff.  Any
# further 2022->2023 incompatibilities (PS CONFIG renames, run flows, ...) must
# be discovered from the Vivado log of the first V03 run and patched one at a
# time, each recorded in the diff.  The pristine tree under $UPSTREAM and the
# fetched commit are never modified.
#
# Usage:
#   make step01_fetch_references FETCH_SET=RFSoC-MTS
#   ./scripts/prepare_mts_2023p2_patch.sh
#   cd build/mts_base_src_2023p2/boards/ZCU208/build_mts && vivado -mode batch -source mts.tcl
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
upstream="${UPSTREAM:-$root/upstream}"
src="$upstream/RFSoC-MTS"
dst="${BUILD:-$root/build}/mts_base_src_2023p2"
pinned_ps="xilinx.com:ip:zynq_ultra_ps_e:3.5"

# Refuse to let this helper drift from the single source of truth.
grep -q "zynq_ultra_ps_e:3.5" "$root/config/ip_versions.tcl" || {
    echo "ERROR: config/ip_versions.tcl no longer pins zynq_ultra_ps_e:3.5; update this helper together with the lock." >&2
    exit 2
}
target="$src/boards/ZCU208/build_mts/mts.tcl"
[[ -f "$target" ]] || {
    echo "ERROR: $target not found. Run: make step01_fetch_references FETCH_SET=RFSoC-MTS" >&2
    exit 3
}
sha="$(git -C "$src" rev-parse HEAD 2>/dev/null || echo unknown)"
expected_sha="$(awk -F'\t' '$1=="RFSoC-MTS"{print $4}' "$root/config/upstream_repositories.tsv")"
if [[ "$sha" != "$expected_sha" ]]; then
    echo "ERROR: RFSoC-MTS checkout is $sha, pinned ref is $expected_sha." >&2
    echo "Re-run: make rebuild STEP=step01_fetch_references FETCH_SET=RFSoC-MTS" >&2
    exit 3
fi

rm -rf "$dst"
mkdir -p "$(dirname "$dst")"
cp -a "$src" "$dst"
rm -rf "$dst/.git"
adapted="$dst/boards/ZCU208/build_mts/mts.tcl"

python3 - "$adapted" "$pinned_ps" <<'PYEOF'
import pathlib, sys
path, pinned = pathlib.Path(sys.argv[1]), sys.argv[2]
old = "xilinx.com:ip:zynq_ultra_ps_e:3.4"
text = path.read_text()
count = text.count(old)
if count == 0:
    sys.exit(f"ERROR: {old} not found in {path}; upstream changed -- re-audit before patching")
path.write_text(text.replace(old, pinned))
print(f"Patched {count} occurrence(s): {old} -> {pinned}")
PYEOF

cat > "$dst/DOA_ADAPTATION_README.txt" <<EOF
Adapted copy for RFSoC_ZCU208_DOA_V7_BuildKit stage V03.
Source: Xilinx/RFSoC-MTS @ $sha (pinned in config/upstream_repositories.tsv)
Generated by: scripts/prepare_mts_2023p2_patch.sh -- do not hand-edit; re-run it.
Only change vs upstream: zynq_ultra_ps_e VLNV 3.4 -> 3.5 (Vivado 2022.1.2 -> 2023.2 lock).
See V03_MTS_BASE_2023P2.md in the DOA repo for the run/validate/accept steps.
EOF

echo "=== Diff vs pristine upstream (must show ONLY the PS VLNV) ==="
diff -u "$target" "$adapted" || true
echo "Adapted tree: $dst"
echo "Next (on the Vivado 2023.2 PC):  cd $dst/boards/ZCU208/build_mts && vivado -mode batch -source mts.tcl"
